<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!academy_ready())redirect('upgrade-multiverse-academy.php');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim($_POST['title']??'');if($title==='')throw new RuntimeException('Course title is required.');$slug=academy_slug($title);db()->prepare('INSERT INTO academy_courses(owner_user_id,slug,title,subtitle,description,category,level,format,price,capacity,starts_at,ends_at,timezone,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([user()['id'],$slug,$title,trim($_POST['subtitle']??''),trim($_POST['description']??''),trim($_POST['category']??'general'),$_POST['level']??'all_levels',$_POST['format']??'self_paced',(float)($_POST['price']??0),($_POST['capacity']??'')!==''?(int)$_POST['capacity']:null,($_POST['starts_at']??'')?:null,($_POST['ends_at']??'')?:null,trim($_POST['timezone']??'America/New_York'),(user()['role']==='admin'?'approved':'pending')]);$id=(int)db()->lastInsertId();db()->prepare("INSERT IGNORE INTO academy_instructors(course_id,user_id,role) VALUES(?,?,'lead')")->execute([$id,user()['id']]);flash('success','Course created.');redirect_route('academy/manage.php',['id'=>$id]);}catch(Throwable $e){flash('error',$e->getMessage());}}
app_header('Create Course');?><section class="form-card wide"><p class="eyebrow">MULTIVERSE ACADEMY</p><h1>Create a Course</h1><form method="post" class="form-grid"><?=csrf_field()?><label>Course title<input name="title" required></label><label>Subtitle<input name="subtitle"></label><label>Category<input name="category" value="general" required></label><label>Level<select name="level"><?php foreach(academy_levels() as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></label><label>Format<select name="format"><?php foreach(academy_formats() as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach?></select></label><label>Price<input type="number" min="0" step="0.01" name="price" value="0"></label><label>Capacity<input type="number" min="1" name="capacity"></label><label>Time zone<input name="timezone" value="America/New_York"></label><label>Starts<input type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label><label class="full">Description<textarea name="description" rows="8"></textarea></label><div class="full"><button class="button primary">Create Course</button></div></form></section><?php app_footer();
